from azure.cosmos import CosmosClient
import os

def get_cosmos_client():
    endpoint = os.environ.get("AZURE_COSMOS_ENDPOINT")
    key = os.environ.get("AZURE_COSMOS_KEY")
    if not endpoint or not key:
        raise ValueError("AZURE_COSMOS_ENDPOINT and AZURE_COSMOS_KEY environment variables must be set.")
    return CosmosClient(endpoint, credential=key)

def get_container_client(database_name, container_name):
    client = get_cosmos_client()
    database = client.get_database_client(database_name)
    container = database.get_container_client(container_name)
    return container

from database_client import get_container_client


def fetch_document(document_id, database_name, container_name, partition_key=None):
    container = get_container_client(database_name, container_name)
    if partition_key:
        document = container.read_item(item=document_id, partition_key=partition_key)
    else:
        document = container.read_item(item=document_id, partition_key=document_id) # Assuming id is partition key if not specified
    return document

from database_client import get_container_client
from azure.cosmos.exceptions import CosmosResourceExistsError, CosmosHttpResponseError


def conditional_update(document_id, updated_document, database_name, container_name, partition_key=None, etag=None):
    container = get_container_client(database_name, container_name)

    # Cosmos DB handles optimistic concurrency with ETag implicitly on replace_item
    # If the item's ETag in the database doesn't match the ETag provided in the request
    # (via _etag field in updated_document), it will raise a 412 Precondition Failed error.
    if etag:
        updated_document['_etag'] = etag

    try:
        if partition_key:
            response = container.replace_item(item=document_id, body=updated_document, partition_key=partition_key)
        else:
            response = container.replace_item(item=document_id, body=updated_document) # Assumes id is partition key if not specified
        return {"status": "success", "document": response}
    except CosmosHttpResponseError as e:
        if e.status_code == 412:  # Precondition Failed
            return {"status": "failed", "message": "Document ETag mismatch. The document has been modified by another operation.", "error": str(e)}
        else:
            raise e

from google.cloud import aiplatform
import os

def check_text_safety(text_content, project_id=None, location=None):
    project_id = project_id or os.environ.get("GCP_PROJECT_ID")
    location = location or os.environ.get("GCP_LOCATION", "us-central1")

    if not project_id:
        raise ValueError("Google Cloud project ID must be provided or set in GCP_PROJECT_ID environment variable.")

    aiplatform.init(project=project_id, location=location)

    # For safety attributes, we can leverage the safety settings of generative models.
    # Using a generative model and accessing its safety attributes in the response.
    try:
        model = aiplatform.GenerativeModel("gemini-pro")
        response = model.generate_content(text_content, 
                                         safety_settings=[
                                             {
                                                 "category": "HARM_CATEGORY_DANGEROUS_CONTENT",
                                                 "threshold": "BLOCK_NONE"
                                             },
                                             {
                                                 "category": "HARM_CATEGORY_HARASSMENT",
                                                 "threshold": "BLOCK_NONE"
                                             },
                                             {
                                                 "category": "HARM_CATEGORY_HATE_SPEECH",
                                                 "threshold": "BLOCK_NONE"
                                             },
                                             {
                                                 "category": "HARM_CATEGORY_SEXUALLY_EXPLICIT",
                                                 "threshold": "BLOCK_NONE"
                                             },
                                         ])
        # The safety attributes are usually part of the response metadata.
        # This example assumes a structure where safety ratings are accessible.
        # Actual implementation might need to parse `response.prompt_feedback` or `response.candidates[0].safety_ratings`
        safety_ratings = []
        if hasattr(response, 'prompt_feedback') and response.prompt_feedback.safety_ratings:
            for rating in response.prompt_feedback.safety_ratings:
                safety_ratings.append({"category": rating.category.name, "probability": rating.probability.name})
        elif hasattr(response, 'candidates') and response.candidates:
            for candidate in response.candidates:
                if hasattr(candidate, 'safety_ratings') and candidate.safety_ratings:
                    for rating in candidate.safety_ratings:
                        safety_ratings.append({"category": rating.category.name, "probability": rating.probability.name})

        return {"status": "success", "safety_ratings": safety_ratings}
    except Exception as e:
        return {"status": "error", "message": str(e)}

import boto3
import os

def archive_record(record_id, content_bytes, bucket_name, object_key=None):
    s3_client = boto3.client('s3')

    if object_key is None:
        object_key = f"archives/{record_id}.json"

    try:
        s3_client.put_object(Bucket=bucket_name, Key=object_key, Body=content_bytes)
        return {"status": "success", "bucket": bucket_name, "key": object_key}
    except Exception as e:
        return {"status": "error", "message": str(e)}
